'use strict';
// Owner and Branch Manager are simulated scopes, never authentication.
let staffActor={role:'Owner'},staffLocation='all',staffMessage='',receivingLines=[],posTicket=[],posHoldToken=null,receiptToken=null;
let lastReceipt=null,lastSale=null,labelSelection=null,labelQty=1,labelWidth=70,labelHeight=40;
let analyticsFilters={period:'30',from:'',to:'',category:'',product:'',min:'',max:''};
const staffModules=[['dashboard','Dashboard'],['pos','POS'],['products','Products & SKUs'],['receiving','Stock Receiving'],['barcodes','Barcode Printing'],['inventory','Inventory'],['transfers','Stock Transfers'],['orders','Orders & Returns'],['prescriptions','Prescription Review'],['lenses','Lens Pricing'],['analytics','Sales Analytics'],['reports','Reports'],['settings','Settings']];
const D=()=>OptimanDemo;
const token=()=>globalThis.crypto?.randomUUID?.()||Date.now()+'-'+Math.random();
const activeLocation=()=>staffActor.role==='Branch Manager'?'khulna':staffLocation==='all'?null:staffLocation;
const staffData=()=>D().snapshot(staffActor,staffActor.role==='Owner'?staffLocation:'khulna');
const catalogName=id=>D().catalog().find(p=>p.id===id)?.name||id;
const locName=id=>D().locations().find(l=>l.id===id)?.name||'Unallocated';
const dateLabel=at=>D().day(at);
function staffHeading(title,text=''){return `<div class="staff-heading"><div><p class="eyebrow">OPTIMAN / OPERATIONS DEMO</p><h1>${title}</h1><p>${text}</p></div></div>`;}
function stockAt(product,location){const b=staffData().balances.find(b=>b.product===product&&b.location===location);return b?b.onHand-b.reserved:0;}
function locationSelect(name='location',value=activeLocation(),all=false){const list=staffActor.role==='Owner'?D().locations():D().locations().filter(l=>l.id==='khulna');return `<select name="${name}" id="staff-${name}" ${staffActor.role==='Branch Manager'?'aria-label="Assigned branch"':''}>${all&&staffActor.role==='Owner'?'<option value="all">All locations</option>':''}${list.map(l=>`<option value="${l.id}" ${l.id===value?'selected':''}>${l.name}</option>`).join('')}</select>`;}
function productSelect(name='product'){return `<select name="${name}" required>${D().catalog().map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.sku)}</option>`).join('')}</select>`;}
function staffTable(headers,rows,empty='No scoped demo records.'){return `<div class="staff-table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(c=>`<tr>${c.map(v=>`<td>${v}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}">${empty}</td></tr>`}</tbody></table></div>`;}
function renderStaff(page){document.body.classList.add('staff-app');const data=staffData();return `<div class="staff-shell"><aside class="staff-sidebar"><a class="logo" href="#home">OPTIMAN</a><p>Retail operations<br><small>Fictional browser-local demo</small></p><nav aria-label="Staff modules">${staffModules.map(([id,label])=>`<a href="#staff/${id}" ${page===id?'aria-current="page"':''}>${label}</a>`).join('')}</nav><a class="back-store" href="#home">Back to storefront</a></aside><div class="staff-content"><div class="staff-toolbar"><label>Demo role<select id="staff-role"><option ${staffActor.role==='Owner'?'selected':''}>Owner</option><option ${staffActor.role==='Branch Manager'?'selected':''}>Branch Manager</option></select></label><label>${staffActor.role==='Owner'?'Location scope':'Fixed assigned branch'}${locationSelect('scope',staffLocation,true)}</label><span>Demo mode selection is NOT authentication.<br>Browser-local state; no device-to-device sync.</span></div><div class="staff-message" role="status">${esc(staffMessage)}</div>${({dashboard:staffDashboard,pos:staffPOS,products:staffProducts,receiving:staffReceiving,barcodes:staffBarcodes,inventory:staffInventory,transfers:staffTransfers,orders:staffOrders,prescriptions:staffPrescriptions,lenses:staffLenses,analytics:staffAnalytics,reports:staffReports,settings:staffSettings}[page]||staffDashboard)(data)}</div></div>`;}
function staffProducts(s){return `${staffHeading('Products & SKUs','One business-wide catalog. Prices and costs here are synthetic configuration, shared by both role modes.')}<div class="staff-actions"><button class="button" id="staff-new-product">Create master SKU</button><label>Find SKU / barcode / model<input id="staff-product-search" type="search" placeholder="Search shared catalog"></label></div>${staffTable(['Model / master SKU','Category / variant','Selling / purchase','Scoped stock','Actions'],s.products.map(p=>[`<b>${esc(p.name)}</b><br>${esc(p.sku)}`,`${esc(p.category)}<br>${esc(p.color)} / ${esc(p.size)}`,`${money(p.price)} / ${p.cost===null?'Cost unavailable':money(p.cost)}<br>${p.status}`,s.balances.filter(b=>b.product===p.id).map(b=>`${locName(b.location)}: ${b.onHand-b.reserved}`).join('<br>')||'0',`<button class="quiet" data-product-edit="${p.id}">Edit shared pricing</button><button class="quiet" data-label-product="${p.id}">Labels</button>`]))}`;}
function productForm(receiving=false){return `<form id="staff-product-form" data-receiving="${receiving}"><h2>New synthetic variant</h2><p>One SKU identifies identical units across every location.</p><label>Master SKU<input name="sku" required pattern="[A-Za-z0-9-]{4,48}" placeholder="OPT-FR-009-BRN-52"></label><label>Model<input name="name" required></label><label>Category<select name="category"><option>Optical Frames</option><option>Sunglasses</option><option>Day-Night</option><option>Polarized</option></select></label><label>Brand<input name="brand" placeholder="Demo brand"></label><label>Frame type<input name="frameType" placeholder="Demo frame"></label><div class="form-grid"><label>Color<input name="color" required></label><label>Size<input name="size" required placeholder="52 · 20 · 145"></label><label>Purchase cost<input name="cost" type="number" min="0" step=".01" required></label><label>Selling price<input name="price" type="number" min="0" step=".01" required></label></div>${receiving?'<label>Receiving quantity<input name="qty" type="number" min="1" step="1" value="1" required></label>':''}<button class="button">${receiving?'Add new SKU to receipt draft':'Create synthetic SKU'}</button><p class="form-error" role="alert"></p></form>`;}
function staffReceiving(s){return `${staffHeading('Supplier stock receiving','Review multiple lines, then confirm once. No stock changes until confirmation.')}<form id="receiving-form" class="staff-panel"><div class="staff-form-grid"><label>Supplier<select id="receive-supplier">${s.suppliers.map(v=>`<option value="${v.id}">${v.name}</option>`).join('')}</select></label><label>Fictional invoice/reference<input id="receive-invoice" required placeholder="DEMO-INV-001"></label><label>Receiving date<input id="receive-date" type="date" value="${D().day()}" required></label><label>Destination${locationSelect('receive-location')}</label></div><div class="staff-form-grid"><label>Existing SKU${productSelect('receive-product')}</label><label>Quantity<input id="receive-qty" type="number" min="1" step="1" value="1"></label><label>Unit purchase cost<input id="receive-cost" type="number" min="0" step=".01" value="1200"></label><label>Selling price · optional<input id="receive-price" type="number" min="0" step=".01" placeholder="Keep current price"></label></div><div class="staff-actions"><button class="quiet" type="button" id="receive-add">Add existing SKU line</button><button class="quiet" type="button" id="receive-new">Add new variant</button></div><div id="receive-lines">${receivingDraft()}</div><button class="button" ${!receivingLines.length?'disabled':''}>Review & confirm receipt</button></form><h2>Scoped receiving history</h2>${staffTable(['Reference','Supplier / invoice','Destination','Items'],s.receipts.slice().reverse().map(r=>[r.id,`${esc(s.suppliers.find(v=>v.id===r.supplier)?.name||r.supplier)}<br>${esc(r.invoice)}`,locName(r.location),r.items.map(l=>`${catalogName(l.product)} × ${l.qty} @ ${money(l.cost)}`).join('<br>')]))}${lastReceipt?`<div class="notice">Last receipt ${lastReceipt.id}. <button class="quiet" data-label-product="${lastReceipt.items[0].product}" data-label-qty="${lastReceipt.items[0].qty}">Generate received labels</button></div>`:''}`;}
function receivingDraft(readonly=false){return staffTable(['SKU','Quantity','Cost / amount',''],receivingLines.map((l,i)=>[esc(l.newProduct?.sku||D().catalog().find(p=>p.id===l.product)?.sku||''),l.qty,`${money(Number(l.cost))} / ${money(Number(l.cost)*Number(l.qty))}`,readonly?'':`<button type="button" class="quiet" data-receive-remove="${i}">Remove</button>`]));}
function labelHTML(p){return `<article class="barcode-label" style="width:${labelWidth}mm;height:${labelHeight}mm"><b>OPTIMAN</b><strong>${esc(p.name)}</strong><small>${esc(p.color)} / ${esc(p.size)}</small>${OptimanBarcode.svg(p.barcode)}<code>${esc(p.sku)}</code><b>${money(p.price)} · Demo price</b></article>`;}
function staffBarcodes(s){const p=s.products.find(p=>p.id===labelSelection)||s.products[0];labelSelection=p.id;const modules=OptimanBarcode.encode(p.barcode).modules;return `${staffHeading('Barcode labels','Valid Code 128-B encodes the master SKU, not individually serialized units. Hardware compatibility is untested.')}<form id="labels-form" class="staff-form-grid"><label>SKU<select id="label-product">${s.products.map(v=>`<option value="${v.id}" ${v.id===p.id?'selected':''}>${esc(v.name)} · ${esc(v.sku)}</option>`).join('')}</select></label><label>Label quantity<input id="label-qty" type="number" min="1" max="100" value="${labelQty}"></label><label>Width · mm<input id="label-width" type="number" min="40" max="120" value="${labelWidth}"></label><label>Height · mm<input id="label-height" type="number" min="30" max="80" value="${labelHeight}"></label><button class="quiet">Update label preview</button></form>${(labelWidth-8)/modules<.2?'<p class="notice">Narrow barcode modules: enlarge the label width for reliable physical scanning.</p>':''}<button class="button" id="print-labels">Print ${labelQty} demo labels</button><div class="labels-preview" id="labels-preview">${Array.from({length:labelQty},()=>labelHTML(p)).join('')}</div>`;}
function printDemo(html,receipt=false){const win=window.open('','_blank');if(!win){staffMessage='Allow browser popups for print preview.';render();return;}win.document.write(`<!doctype html><html><head><title>Optiman demo print</title><style>@page{size:${receipt?'80mm 297mm':'A4'};margin:3mm}body{font:11px Arial;color:black;margin:0}.labels-preview{display:flex;flex-wrap:wrap;gap:2mm}.barcode-label{box-sizing:border-box;padding:3mm;display:flex;flex-direction:column;align-items:center;justify-content:space-between;break-inside:avoid;border:1px solid #ddd;overflow:hidden}.barcode-label small{font-size:8px}.barcode-label strong{font-size:10px}.barcode-label code{font-size:8px}.barcode-svg{height:12mm;width:100%;display:block}.receipt{width:72mm;text-align:center}.receipt table{width:100%;font-size:10px}.receipt p{font-size:10px}.receipt hr{border:0;border-top:1px dashed black}</style></head><body>${html}</body></html>`);win.document.close();win.focus();win.print();}
async function staffCommand(type,data,key=token()){const result=await D().command(type,data,staffActor,key);staffMessage=`${type}: simulated command ${result.id||'completed'}. Shared demo state updated.`;return result;}
const staffRoot=document.querySelector('main');
staffRoot.addEventListener('input',e=>{if(e.target.id==='staff-product-search'){const q=e.target.value.toLowerCase();staffRoot.querySelectorAll('tbody tr').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(q));}});
staffRoot.addEventListener('change',e=>{
 if(e.target.id==='staff-role'){staffActor={role:e.target.value};staffLocation=staffActor.role==='Branch Manager'?'khulna':'all';posTicket=[];receivingLines=[];lastSale=null;lastReceipt=null;staffMessage='Demo scope changed. This is not authentication.';render();}
 if(e.target.id==='staff-scope'){staffLocation=e.target.value;posTicket=[];lastSale=null;lastReceipt=null;render();}
});
document.addEventListener('click',async e=>{
 const b=e.target.closest('button');if(!b)return;const d=b.dataset;
 try{
  if(b.id==='staff-new-product'||b.id==='receive-new'){modal(productForm(b.id==='receive-new'));}
  if(d.productEdit){const p=D().catalog().find(p=>p.id===d.productEdit);modal(`<form id="product-price-form" data-product="${p.id}"><h2>Shared catalog pricing</h2><p>${esc(p.name)} · ${esc(p.sku)}</p><label>Selling price<input name="price" type="number" min="0" step=".01" value="${p.price}" required></label><label>Purchase cost · blank if unknown<input name="cost" type="number" min="0" step=".01" value="${p.cost??''}"></label><label>Audience tags · optional<input name="audiences" value="${esc((p.audiences||[]).join(', '))}" placeholder="Men, Women, Kids"></label><p>Assign only supplied audience metadata; tags do not duplicate a SKU or verify fit.</p><label>Status<select name="status"><option ${p.status==='active'?'selected':''}>active</option><option ${p.status==='inactive'?'selected':''}>inactive</option></select></label><button class="button">Confirm shared change</button><p class="form-error" role="alert"></p></form>`);}
  if(b.id==='receive-add'){if(document.querySelector('#receive-cost').value==='')throw Error('Enter an explicit unit purchase cost.');const product=staffRoot.querySelector('[name=receive-product]').value,qty=Number(document.querySelector('#receive-qty').value),cost=Number(document.querySelector('#receive-cost').value),price=document.querySelector('#receive-price').value;if(!Number.isInteger(qty)||qty<1||!Number.isFinite(cost)||cost<0)throw Error('Positive whole quantity and nonnegative unit cost required.');receivingLines.push({product,qty,cost,price});document.querySelector('#receive-lines').innerHTML=receivingDraft();document.querySelector('#receiving-form>.button').disabled=false;}
  if(d.receiveRemove!==undefined){receivingLines.splice(+d.receiveRemove,1);document.querySelector('#receive-lines').innerHTML=receivingDraft();document.querySelector('#receiving-form>.button').disabled=!receivingLines.length;}
  if(d.labelProduct){labelSelection=d.labelProduct;labelQty=Math.min(100,Number(d.labelQty)||1);location.hash='staff/barcodes';if(location.hash==='#staff/barcodes')render();}
  if(b.id==='confirm-receipt'){b.disabled=true;try{lastReceipt=await staffCommand('receive',receiptToken.payload,receiptToken.key);receivingLines=[];document.querySelector('dialog').close();render();}catch(err){b.disabled=false;throw err;}}
  if(b.id==='print-labels')printDemo('<div class="labels-preview">'+document.querySelector('#labels-preview').innerHTML+'</div>');
 }catch(err){staffMessage=err.message;const error=document.querySelector('dialog[open] .form-error');if(error)error.textContent=err.message;else{const status=document.querySelector('.staff-message');if(status)status.textContent=err.message;}}
});
document.addEventListener('submit',async e=>{
 const form=e.target;if(!['staff-product-form','product-price-form','receiving-form','labels-form'].includes(form.id))return;e.preventDefault();
 try{
  const values=Object.fromEntries(new FormData(form));
  if(form.id==='staff-product-form'){if(form.dataset.receiving==='true'){receivingLines.push({newProduct:values,qty:Number(values.qty),cost:Number(values.cost),price:values.price});document.querySelector('dialog').close();document.querySelector('#receive-lines').innerHTML=receivingDraft();document.querySelector('#receiving-form>.button').disabled=false;}else{await staffCommand('createProduct',values);document.querySelector('dialog').close();render();}}
  if(form.id==='product-price-form'){await staffCommand('updateProduct',{product:form.dataset.product,...values});document.querySelector('dialog').close();render();}
  if(form.id==='receiving-form'){receiptToken={key:token(),payload:{supplier:document.querySelector('#receive-supplier').value,invoice:document.querySelector('#receive-invoice').value,date:document.querySelector('#receive-date').value,location:document.querySelector('#staff-receive-location').value,items:cloneRx(receivingLines)}};modal(`<h2>Review synthetic receipt</h2><p>${esc(receiptToken.payload.invoice)} · ${locName(receiptToken.payload.location)}</p>${receivingDraft(true)}<p>Purchase total: ${money(receivingLines.reduce((n,l)=>n+Number(l.qty)*Number(l.cost),0))}</p><button class="button" id="confirm-receipt">Confirm receipt once</button><p class="form-error" role="alert"></p>`);}
  if(form.id==='labels-form'){labelSelection=document.querySelector('#label-product').value;labelQty=Number(document.querySelector('#label-qty').value);labelWidth=Number(document.querySelector('#label-width').value);labelHeight=Number(document.querySelector('#label-height').value);if(labelQty<1||labelQty>100||labelWidth<40||labelWidth>120||labelHeight<30||labelHeight>80)throw Error('Use 1–100 labels, width 40–120mm and height 30–80mm.');render();}
 }catch(err){const error=form.querySelector('.form-error')||document.querySelector('.staff-message');if(error)error.textContent=err.message;}
});

let posLocation='khulna',posFinalization=null,rxPOSContext=null;
function posBranch(){return activeLocation()||posLocation;}
function ticketTotal(){const rules=D().lensRules();return posTicket.reduce((n,l)=>n+(D().catalog().find(p=>p.id===l.product).price+(l.lensId==null?0:Number(rules[l.lensId]?.price||0)))*l.qty,0);}
function ticketAdd(p){if(!p)throw Error('SKU / barcode not found.');const loc=posBranch();if(stockAt(p.id,loc)<1)throw Error('No available stock at active branch.');const existing=posTicket.find(l=>l.product===p.id&&!l.rx);if(existing)existing.qty++;else posTicket.push({product:p.id,qty:1,lensId:null,rxType:null});posFinalization=null;render();document.querySelector('#pos-scan')?.focus();}
function ticketHTML(){return posTicket.map((l,i)=>{const p=D().catalog().find(p=>p.id===l.product),rule=l.lensId==null?null:D().lensRules()[l.lensId];return `<article class="pos-line"><div><b>${esc(p.name)}</b><small>${esc(p.sku)} · available ${stockAt(p.id,posBranch())}</small><p>Frame ${money(p.price)}${rule?' + lenses '+money(rule.price):''} per pair</p><p>${esc(l.rx?rxSummary(l.rx):'Frame Only')}</p><button class="text-button" data-ticket-config="${i}">Configure lenses / prescription</button></div><div class="quantity"><button data-ticket-qty="${i}" data-delta="-1" aria-label="Reduce ${p.name}">−</button><b>${l.qty}</b><button data-ticket-qty="${i}" data-delta="1" aria-label="Increase ${p.name}">+</button><button class="quiet" data-ticket-remove="${i}">Remove</button></div></article>`;}).join('');}
function staffPOS(s){const loc=posBranch(),location=D().locations().find(l=>l.id===loc);return `${staffHeading('Branch point of sale','Synthetic sale confirmation deducts the same demo stock used by the storefront. No real payment.')}<div class="pos-register"><b>${locName(loc)} / Register DEMO-01</b>${staffActor.role==='Owner'?`<label>Active POS location<select id="pos-location">${D().locations().filter(l=>l.type==='branch').map(l=>`<option value="${l.id}" ${l.id===loc?'selected':''}>${l.name}</option>`).join('')}</select></label>`:''}<span id="pos-connection">${navigator.onLine?'Browser online':'OFFLINE · finalization blocked'}</span><button class="quiet" id="pos-offline-toggle">Simulate ${offline?'online':'offline'}</button></div>${offline?'<p class="notice">Offline simulation: sale finalization is blocked.</p>':''}${location?.type!=='branch'?'<p class="notice">Choose a branch for POS. Receiving/inventory remain available at warehouse.</p>':''}<div class="retail-pos"><section><form id="pos-scan-form"><label>Scan barcode / master SKU / model<input id="pos-scan" autocomplete="off" placeholder="OPT-FR-001-BRN-52 or Atlas"></label><button class="button">Add scanned item</button></form><label>Find product<input id="pos-product-search" type="search" placeholder="SKU, category, name"></label><div id="pos-product-results" class="pos-catalog">${posResults('')}</div></section><aside class="staff-panel"><h2>Current sale</h2>${posTicket.length?ticketHTML():'<p>Scan or choose a synthetic SKU.</p>'}<div class="pos-total"><span>Frame + lens subtotal</span><b>${money(ticketTotal())}</b></div><p class="muted">Tax/discounts not configured. No real payment. Unknown lens cost is excluded from profit claims.</p><label>Simulated tender<select id="pos-payment"><option>Cash</option><option>Card</option><option>Mobile financial service</option></select></label><button class="button" id="pos-complete" ${!posTicket.length||offline||!navigator.onLine||location?.type!=='branch'?'disabled':''}>Complete simulated sale</button><div class="staff-actions"><button class="quiet" id="pos-hold" ${!posTicket.length?'disabled':''}>Hold frame-only sale</button><button class="quiet" id="pos-cancel">Cancel current sale</button></div>${lastSale?`<p>Last simulated transaction: <b>${lastSale.id}</b></p><button class="quiet" data-sale-receipt="${lastSale.id}">Receipt / print</button>`:''}</aside></div><h2>Held sales · no stock reservation</h2>${staffTable(['Reference','Branch','Lines',''],s.holds.map(h=>[h.id,locName(h.location),h.items.length,`<button class="quiet" data-pos-resume="${h.id}">Resume</button>`]))}<h2>Transaction history / register summary</h2><p>Today's scoped completed sales: ${s.sales.filter(x=>dateLabel(x.at)===D().day()).length} · ${money(s.sales.filter(x=>dateLabel(x.at)===D().day()).reduce((n,x)=>n+x.total,0))} before refunds. See analytics for net amounts.</p>${salesHistory(s)}`;}
function posResults(q){return D().catalog().filter(p=>p.status==='active'&&(p.name+' '+p.sku+' '+p.category).toLowerCase().includes(q.toLowerCase())).map(p=>`<button type="button" data-ticket-add="${p.id}"><b>${esc(p.name)}</b><small>${esc(p.sku)}</small><span>${money(p.price)} · ${stockAt(p.id,posBranch())} available</span></button>`).join('');}
function salesHistory(s){return staffTable(['Reference / date','Branch','Sale total',''],s.sales.slice().reverse().map(sale=>[`${sale.id}<br>${dateLabel(sale.at)}`,locName(sale.location),money(sale.total),`<button class="quiet" data-sale-receipt="${sale.id}">Receipt</button><button class="quiet" data-return-sale="${sale.id}">Return / refund</button>`]));}
function receiptHTML(sale){return `<div class="receipt" id="sale-receipt"><h2>OPTIMAN</h2><p>SIMULATED RECEIPT · NOT A REAL PAYMENT<br>${sale.id}<br>${locName(sale.location)} / DEMO-01<br>${dateLabel(sale.at)} · ${esc(sale.payment)}</p><hr>${sale.items.map(l=>`<p>${esc(l.name)} × ${l.qty}<br>Frame ${money(l.framePrice)} + lenses ${money(l.lensPrice)}<br>${esc(l.lensCategory)} · ${money((l.framePrice+l.lensPrice)*l.qty)}</p>`).join('')}<hr><b>Demo subtotal ${money(sale.total)}</b><p>Tax / delivery not configured.<br>80mm layout; hardware and auto-cut untested.</p></div>`;}
function preparePOSRx(){if(!rxPOSContext)return;if(!location.hash.startsWith('#product/'+rxPOSContext.product)){rxPOSContext=null;return;}const line=posTicket[rxPOSContext.index];rxDraft=line.rx?cloneRx(line.rx):freshRx();rxDraft.qty=line.qty;lens=!!line.rx;rxEditing=-1;}
function savePOSRx(line){const index=rxPOSContext.index;posTicket[index]={product:line.id,qty:line.qty,lensId:line.rx?.lensId??null,rxType:line.rx?.type??null,rx:line.rx};rxPOSContext=null;posFinalization=null;location.hash='staff/pos';}
document.querySelector('main').addEventListener('input',e=>{if(e.target.id==='pos-product-search')document.querySelector('#pos-product-results').innerHTML=posResults(e.target.value);});
document.querySelector('main').addEventListener('change',e=>{if(e.target.id==='pos-location'){posLocation=e.target.value;if(staffActor.role==='Owner'&&staffLocation!=='all')staffLocation=posLocation;posTicket=[];render();}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;try{
 if(d.ticketAdd)ticketAdd(D().catalog().find(p=>p.id===d.ticketAdd));
 if(d.ticketQty!==undefined){const i=+d.ticketQty;posTicket[i].qty+=Number(d.delta);if(posTicket[i].qty<=0)posTicket.splice(i,1);posFinalization=null;render();}
 if(d.ticketRemove!==undefined){posTicket.splice(+d.ticketRemove,1);posFinalization=null;render();}
 if(d.ticketConfig!==undefined){const i=+d.ticketConfig;rxPOSContext={index:i,product:posTicket[i].product,location:posBranch()};location.hash='product/'+posTicket[i].product;}
 if(b.id==='pos-offline-toggle'){offline=!offline;render();}
 if(b.id==='pos-cancel'){posTicket=[];posFinalization=null;render();}
 if(b.id==='pos-hold'){await staffCommand('hold',{location:posBranch(),items:posTicket});posTicket=[];render();}
 if(d.posResume){const hold=await staffCommand('resume',{id:d.posResume});posLocation=hold.location;if(staffActor.role==='Owner'&&staffLocation!=='all')staffLocation=hold.location;posTicket=hold.items;render();}
 if(b.id==='pos-complete'){if(offline||!navigator.onLine)throw Error('Offline: cannot finalize a demo sale.');posFinalization={key:token(),payload:{location:posBranch(),payment:document.querySelector('#pos-payment').value,expectedTotal:ticketTotal(),items:cloneRx(posTicket)}};modal(`<h2>Confirm simulated sale</h2><p>${locName(posBranch())} · ${money(ticketTotal())}. This will deduct shared browser-local demo stock.</p><button class="button" id="pos-confirm">Confirm once</button><p class="form-error" role="alert"></p>`);}
 if(b.id==='pos-confirm'){b.disabled=true;try{if(offline||!navigator.onLine)throw Error('Offline: finalization blocked.');lastSale=await staffCommand('sale',posFinalization.payload,posFinalization.key);posTicket=[];render();modal(receiptHTML(lastSale)+'<button class="button" id="pos-print-receipt">Print 80mm preview</button>');}catch(err){b.disabled=false;throw err;}}
 if(d.saleReceipt){const sale=staffData().sales.find(x=>x.id===d.saleReceipt);if(!sale)throw Error('Transaction outside current scope.');modal(receiptHTML(sale)+'<button class="button" id="pos-print-receipt">Print 80mm preview</button>');}
 if(b.id==='pos-print-receipt')printDemo(document.querySelector('#sale-receipt').outerHTML,true);
 }catch(err){staffMessage=err.message;const target=document.querySelector('dialog[open] .form-error')||document.querySelector('.staff-message');if(target)target.textContent=err.message;}});
document.addEventListener('submit',e=>{if(e.target.id==='pos-scan-form'){e.preventDefault();try{ticketAdd(D().lookup(document.querySelector('#pos-scan').value.trim()));}catch(err){staffMessage=err.message;document.querySelector('.staff-message').textContent=err.message;}}});

let inventoryFilter={query:'',category:'',state:''};
function inventoryRows(s){return s.balances.filter(b=>{const p=s.products.find(p=>p.id===b.product),q=inventoryFilter.query.toLowerCase(),av=b.onHand-b.reserved;return (!q||(p.name+' '+p.sku+' '+p.barcode).toLowerCase().includes(q))&&(!inventoryFilter.category||p.category===inventoryFilter.category)&&(!inventoryFilter.state||(inventoryFilter.state==='out'?av===0:av>0&&av<=s.settings.lowStock));}).map(b=>{const p=s.products.find(p=>p.id===b.product),av=b.onHand-b.reserved,transit=s.transfers.filter(t=>t.destination===b.location&&t.product===b.product&&t.status==='in_transit').reduce((n,t)=>n+t.qty-t.received,0);return [`<b>${esc(p.name)}</b><br>${esc(p.sku)}`,locName(b.location),b.onHand,b.reserved,av,transit,b.quarantine,av===0?'Out of stock':av<=s.settings.lowStock?'Low stock':'Available',Math.max(0,5-av)+' units · demo target 5'];});}
function staffInventory(s){return `${staffHeading('Inventory by location','Available = sellable on-hand − reserved. In-transit and quarantine units are excluded from online availability.')}<div class="staff-form-grid"><label>SKU / barcode / model<input id="inventory-query" value="${esc(inventoryFilter.query)}" placeholder="Search inventory"></label><label>Category<select id="inventory-category"><option value="">All categories</option>${[...new Set(s.products.map(p=>p.category))].map(v=>`<option ${inventoryFilter.category===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label>Stock state<select id="inventory-state"><option value="">All stock</option><option value="low" ${inventoryFilter.state==='low'?'selected':''}>Low stock</option><option value="out" ${inventoryFilter.state==='out'?'selected':''}>Out of stock</option></select></label></div><div id="inventory-results">${staffTable(['SKU','Location','On-hand','Reserved','Available','Inbound transit','Quarantine','State','Reorder suggestion'],inventoryRows(s))}</div><details class="staff-panel"><summary>Record stock adjustment</summary><form id="adjust-form" class="staff-form-grid"><label>Location${locationSelect('adjust-location')}</label><label>SKU${productSelect()}</label><label>Signed whole quantity<input name="delta" type="number" step="1" required placeholder="2 or -1"></label><label>Reason<input name="reason" required placeholder="Synthetic stocktake correction"></label><button class="button">Confirm adjustment</button></form></details><h2>Scoped movement history</h2>${staffTable(['Reference / date','SKU','Location','Physical delta','Reserved delta','Reason'],s.movements.slice().reverse().slice(0,150).map(m=>[`${m.reference}<br>${dateLabel(m.at)}`,catalogName(m.product),locName(m.location),m.delta,m.reservedDelta,esc(m.reason)]))}<p class="muted">Latest 150 scoped movements shown. Export the report for all scoped entries.</p><h2>Supplier receiving / transfer history</h2><p>${s.receipts.length} supplier receipts · ${s.transfers.length} relevant transfers</p><a class="button" href="#staff/receiving">Receiving history</a> <a class="quiet" href="#staff/transfers">Transfer history</a>`;}
function transferLocations(name){return `<select name="${name}">${D().locations().map(l=>`<option value="${l.id}">${l.name}</option>`).join('')}</select>`;}
function staffTransfers(s){return `${staffHeading('Stock transfers','No approval hierarchy. Source-scoped dispatch and destination-scoped receipt. Partial receipt keeps the remainder in transit.')}<form id="transfer-form" class="staff-panel staff-form-grid"><label>Source${transferLocations('source')}</label><label>Destination${transferLocations('destination')}</label><label>Master SKU${productSelect()}</label><label>Quantity<input name="qty" type="number" min="1" step="1" value="1" required></label><button class="button">Create transfer</button></form><p class="muted">Branch Manager may request transfers involving Khulna, dispatch from Khulna, and receive into Khulna. They cannot mutate another location's balance. Cancelling dispatched remainder requires source scope and returns the remaining transit units to origin.</p>${staffTable(['Transfer','Route / SKU','Qty / received','State','Actions'],s.transfers.slice().reverse().map(t=>[t.id,`${locName(t.source)} → ${locName(t.destination)}<br>${esc(catalogName(t.product))}`,`${t.qty} / ${t.received}`,t.status,`${t.status==='planned'&&(staffActor.role==='Owner'||t.source==='khulna')?`<button class="quiet" data-transfer-dispatch="${t.id}">Dispatch</button>`:''}${t.status==='in_transit'&&(staffActor.role==='Owner'||t.destination==='khulna')?`<button class="quiet" data-transfer-receive="${t.id}" data-remaining="${t.qty-t.received}">Receive partial / full</button>`:''}${(t.status==='planned'||t.status==='in_transit'&&(staffActor.role==='Owner'||t.source==='khulna'))?`<button class="quiet" data-transfer-cancel="${t.id}">Cancel remainder</button>`:''}`]))}`;}
document.querySelector('main').addEventListener('input',e=>{if(e.target.id==='inventory-query'){inventoryFilter.query=e.target.value;document.querySelector('#inventory-results').innerHTML=staffTable(['SKU','Location','On-hand','Reserved','Available','Inbound transit','Quarantine','State','Reorder suggestion'],inventoryRows(staffData()));}});
document.querySelector('main').addEventListener('change',e=>{if(e.target.id==='inventory-category'||e.target.id==='inventory-state'){inventoryFilter[e.target.id==='inventory-category'?'category':'state']=e.target.value;render();}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;try{
 if(d.transferDispatch){await staffCommand('transferDispatch',{id:d.transferDispatch});render();}
 if(d.transferCancel){modal(`<h2>Cancel transfer remainder?</h2><p>Planned transfers change no stock. Any unreceived in-transit remainder returns to its origin once.</p><button class="button" data-transfer-cancel-confirm="${d.transferCancel}">Confirm cancellation</button><p class="form-error" role="alert"></p>`);}
 if(d.transferCancelConfirm){b.disabled=true;await staffCommand('transferCancel',{id:d.transferCancelConfirm});document.querySelector('dialog').close();render();}
 if(d.transferReceive){modal(`<form id="transfer-receive-form" data-transfer="${d.transferReceive}"><h2>Receive transfer</h2><label>Quantity actually received<input name="qty" type="number" min="1" max="${d.remaining}" value="${d.remaining}" step="1" required></label><button class="button">Confirm receipt once</button><p class="form-error" role="alert"></p></form>`);}
 }catch(err){const error=document.querySelector('dialog[open] .form-error')||document.querySelector('.staff-message');if(error)error.textContent=err.message;}});
document.addEventListener('submit',async e=>{const form=e.target;if(!['adjust-form','transfer-form','transfer-receive-form'].includes(form.id))return;e.preventDefault();const button=form.querySelector('button');try{button.disabled=true;const data=Object.fromEntries(new FormData(form));if(form.id==='adjust-form')await staffCommand('adjust',{...data,location:document.querySelector('#staff-adjust-location').value});if(form.id==='transfer-form')await staffCommand('transferCreate',data);if(form.id==='transfer-receive-form'){await staffCommand('transferReceive',{id:form.dataset.transfer,qty:data.qty});document.querySelector('dialog').close();}render();}catch(err){button.disabled=false;const target=form.querySelector('.form-error')||document.querySelector('.staff-message');if(target)target.textContent=err.message;}});

function kpi(label,value,href,detail=''){return `<a class="retail-kpi" href="${href}"><span>${label}</span><strong>${value}</strong><small>${detail}</small></a>`;}
function staffDashboard(s){const today=D().analytics(staffActor,{location:staffLocation,from:D().day(),to:D().day()}),month=D().analytics(staffActor,{location:staffLocation,from:D().day().slice(0,7)+'-01',to:D().day()}),rows=s.products.map(p=>({p,q:s.balances.filter(b=>b.product===p.id).reduce((n,b)=>n+b.onHand-b.reserved,0)})),low=rows.filter(r=>r.q>0&&r.q<=s.settings.lowStock).length,out=rows.filter(r=>r.q===0).length,missing=s.balances.some(b=>b.onHand&&s.products.find(p=>p.id===b.product).cost===null),value=s.balances.reduce((n,b)=>n+b.onHand*(s.products.find(p=>p.id===b.product).cost||0),0);return `${staffHeading(staffActor.role==='Owner'?'Business overview':'Khulna branch overview','KPIs use completed POS/dispatched online sales and actual scoped synthetic ledger data. Returns reduce net revenue.')}<div class="retail-kpis">${kpi("Today's net sales",money(today.total),'#staff/analytics')}${kpi('This month · net sales',money(month.total),'#staff/analytics')}${kpi('Units sold · month',month.units,'#staff/analytics','Net of returned units')}${kpi('Transactions · month',month.transactions,'#staff/pos')}${kpi('Average transaction · month',month.average===null?'Unavailable':money(Math.round(month.average)),'#staff/analytics','Net revenue / completed sales')}${kpi('Physical inventory cost',missing?'Partially unavailable':money(value),'#staff/inventory',missing?'Known recorded cost: '+money(value):'Reserved included; transit/quarantine excluded')}${kpi('Low-stock SKUs',low,'#staff/inventory')}${kpi('Out-of-stock SKUs',out,'#staff/inventory')}${kpi('Pending transfers',s.transfers.filter(t=>['planned','in_transit'].includes(t.status)).length,'#staff/transfers')}${kpi('Pending online orders',s.orders.filter(o=>['reserved','allocation_exception'].includes(o.status)).length,'#staff/orders')}${kpi('Prescription reviews',s.orders.filter(o=>['Pending','Needs clarification','Revised quote awaiting customer acceptance'].includes(o.review)).length,'#staff/prescriptions')}</div><div class="staff-chart-grid"><section class="staff-panel"><h2>Month's sales trend</h2>${lineChart(month.daily,'Daily net revenue')}</section><section class="staff-panel"><h2>Month's category sales</h2>${barChart(month.category,'Category net revenue')}</section></div><div class="staff-actions"><a class="button" href="#staff/pos">Open branch POS</a><a class="quiet" href="#staff/receiving">Receive supplier stock</a><a class="quiet" href="#staff/analytics">Explore analytics</a></div>`;}
function lineChart(rows,title){if(!rows.length)return '<p>No matching completed sales or refunds for this period.</p>';const values=rows.map(r=>r.revenue),min=Math.min(0,...values),max=Math.max(1,...values),range=Math.max(1,max-min);const points=rows.map((r,i)=>`${40+i*520/Math.max(1,rows.length-1)},${190-(r.revenue-min)/range*155}`).join(' ');return `<svg class="sales-line-chart" viewBox="0 0 600 240" role="img" aria-label="${esc(title)}"><title>${esc(title)}</title><line x1="40" y1="190" x2="565" y2="190" stroke="#b58b64"/><polyline points="${points}" fill="none" stroke="#2b1d17" stroke-width="3"/>${rows.map((r,i)=>`<circle cx="${40+i*520/Math.max(1,rows.length-1)}" cy="${190-(r.revenue-min)/range*155}" r="4" fill="#4a3328"><title>${esc(r.label)}: ${money(r.revenue)} / ${r.units} units</title></circle>`).join('')}<text x="40" y="220">${esc(rows[0].label)}</text><text x="560" y="220" text-anchor="end">${esc(rows.at(-1).label)}</text><text x="40" y="22">${money(max)}</text></svg><p class="muted">Hover points for exact values. Negative net amounts represent refunds. Gaps are dates without events.</p>`;}
function barChart(rows,title){if(!rows.length)return '<p>No matching data.</p>';const max=Math.max(1,...rows.map(r=>Math.abs(r.revenue)));return `<div class="sales-bars" role="img" aria-label="${esc(title)}">${rows.map(r=>`<div><span>${esc(r.label)}</span><div class="bar-track"><i style="width:${Math.abs(r.revenue)/max*100}%"></i></div><b>${money(r.revenue)}</b><small>${r.units} units</small></div>`).join('')}</div>`;}
function getAnalytics(){const filters={location:staffLocation,...analyticsFilters};if(filters.period!=='custom'){const days=Number(filters.period||30);filters.from=D().day(new Date(Date.now()-(days-1)*86400000));filters.to=D().day();}if(!filters.from||!filters.to||filters.from>filters.to)throw Error('Choose a valid date range.');if((filters.min!==''&&(!Number.isFinite(Number(filters.min))||Number(filters.min)<0))||(filters.max!==''&&(!Number.isFinite(Number(filters.max))||Number(filters.max)<0))||(filters.min!==''&&filters.max!==''&&Number(filters.min)>Number(filters.max)))throw Error('Choose a valid minimum/maximum price range.');return D().analytics(staffActor,filters);}
function analyticsControls(s){return `<form id="analytics-filters" class="staff-panel staff-form-grid"><label>Period<select name="period">${[['1','Today'],['7','Last 7 days'],['30','Last 30 days'],['90','Last 90 days'],['custom','Custom range']].map(([v,l])=>`<option value="${v}" ${analyticsFilters.period===v?'selected':''}>${l}</option>`).join('')}</select></label><label>From<input type="date" name="from" value="${analyticsFilters.from}"></label><label>To<input type="date" name="to" value="${analyticsFilters.to}"></label><label>Category<select name="category"><option value="">All categories</option>${[...new Set(s.products.map(p=>p.category))].map(v=>`<option ${v===analyticsFilters.category?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label>SKU / model<select name="product"><option value="">All SKUs</option>${s.products.map(p=>`<option value="${p.id}" ${analyticsFilters.product===p.id?'selected':''}>${esc(p.name)} / ${esc(p.sku)}</option>`).join('')}</select></label><label>Minimum frame price<input name="min" type="number" min="0" value="${analyticsFilters.min}"></label><label>Maximum frame price<input name="max" type="number" min="0" value="${analyticsFilters.max}"></label><button class="button">Apply report filters</button></form>`;}
function bandLeaders(rows){if(!rows.length)return '';const ties=(key,max)=>{const value=Math[max?'max':'min'](...rows.map(r=>r[key]));return rows.filter(r=>r[key]===value).map(r=>r.label).join(', ');};return `<p class="muted">Highest quantity: ${esc(ties('units',true))}. Lowest quantity: ${esc(ties('units',false))}. Highest revenue: ${esc(ties('revenue',true))}. Lowest revenue: ${esc(ties('revenue',false))}. Ties are included.</p>`;}
function analyticsBody(a){const low=a.ranking.slice().sort((x,y)=>x.units-y.units);return `<div class="retail-kpis">${kpi('Filtered net revenue',money(a.total),'#staff/reports')}${kpi('Filtered net units',a.units,'#staff/reports')}${kpi('Refunds',money(a.refunds),'#staff/orders')}${kpi('Gross profit',a.profit===null?'Unavailable':money(a.profit),'#staff/reports',a.profit===null?'Incomplete frame or lens cost snapshots':'Recorded frame + lens cost basis')}</div><div class="staff-chart-grid"><section class="staff-panel"><h2>Daily sales trend</h2>${lineChart(a.daily,'Daily sales')}</section><section class="staff-panel"><h2>Weekly sales trend</h2>${lineChart(a.weekly,'Weekly sales')}</section><section class="staff-panel"><h2>Monthly sales trend</h2>${lineChart(a.monthly,'Monthly sales')}</section><section class="staff-panel"><h2>Category quantity & revenue</h2>${barChart(a.category,'Category performance')}</section><section class="staff-panel"><h2>Frame-price band performance</h2>${barChart(a.bands,'Price range performance')}${bandLeaders(a.bands)}<p class="muted">Bands are configurable synthetic ranges. Revenue includes the configured frame and lens pair; band assignment uses frame price.</p></section><section class="staff-panel"><h2>Sales by ${staffActor.role==='Owner'?'branch / location':'assigned branch'}</h2>${barChart(a.branch,'Branch performance')}</section><section class="staff-panel"><h2>Lens category sales</h2>${barChart(a.lenses,'Lens pair revenue only')}<p class="muted">Lens revenue only; frame revenue is excluded here.</p></section><section class="staff-panel"><h2>Revenue versus units</h2>${staffTable(['Category','Net revenue','Net units'],a.category.map(r=>[esc(r.label),money(r.revenue),r.units]))}</section></div><h2>Best-selling SKUs</h2>${rankedTable(a.ranking)}<h2>Lowest-selling / zero-sales SKUs</h2>${rankedTable(low)}<h2>Slow-moving inventory & turnover indicators</h2>${staffTable(['SKU','Available','Catalog / replenishment age · days','Units / day','History assessment','Turnover proxy'],a.ranking.map(r=>[`${esc(r.label)}<br>${esc(r.sku)}`,r.available,`${r.age} / ${r.stockAge}`,r.velocity.toFixed(2),r.status,r.turnover===null?'Unavailable':r.turnover.toFixed(2)]))}<p class="muted">Synthetic age is days since catalog introduction / last replenishment movement (not FIFO lot age); velocity uses the selected period. Turnover is a unit-based estimate using closing availability and net units to infer average stock, not audited financial turnover. Under 30 days is insufficient history, not a zero-sales conclusion. Gross profit is unavailable when any relevant cost snapshot is missing; known-cost contribution alone is ${money(a.knownProfit)}.</p>`;}
function rankedTable(rows){return staffTable(['SKU / model','Net units','Net revenue','Available'],rows.map(r=>[`${esc(r.label)}<br>${esc(r.sku)}`,r.units,money(r.revenue),r.available]));}
function staffAnalytics(s){let a;try{a=getAnalytics();}catch(err){return staffHeading('Sales analytics')+analyticsControls(s)+`<p class="notice">${esc(err.message)}</p>`;}return `${staffHeading('Sales analytics',`${a.from} to ${a.to} · Asia/Dhaka business dates · scoped synthetic records`)}${analyticsControls(s)}${analyticsBody(a)}`;}
function staffReports(s){let a;try{a=getAnalytics();}catch(err){return staffHeading('Reports')+`<p class="notice">${esc(err.message)}</p><a class="button" href="#staff/analytics">Correct report filters</a>`;}return `${staffHeading('Reports & exports','Exports contain scoped synthetic operational data only. No prescription measurements or customer information.')}<div class="staff-actions"><button class="button" data-export="sales">Export scoped sales CSV</button><button class="quiet" data-export="movements">Export scoped movement CSV</button><button class="quiet" data-export="inventory">Export scoped inventory CSV</button><a class="quiet" href="#staff/analytics">Change report filters</a></div><p>Sales export uses current analytics filters (${a.from} through ${a.to}). Inventory/movement exports use the current location scope.</p>${staffTable(['Report','Current result'],[['Completed sale transactions',a.transactions],['Net revenue',money(a.total)],['Net units',a.units],['Returns/refunds',money(a.refunds)],['Gross profit',a.profit===null?'Unavailable (missing costs)':money(a.profit)],['Scoped movement records',s.movements.length],['Scoped receipts',s.receipts.length],['Relevant transfers',s.transfers.length]])}`;}
function exportCSV(kind){const s=staffData(),a=getAnalytics();let rows;if(kind==='sales')rows=[['Sale','Date','Location','SKU','Category','Qty','Net revenue','Gross profit'],...a.rows.map(r=>[r.sale,dateLabel(r.at),locName(r.location),r.sku,r.category,r.qty,r.revenue,r.profit===null?'Unavailable':r.profit])];else if(kind==='movements')rows=[['Reference','Date','Location','SKU','Physical delta','Reserved delta','Reason'],...s.movements.map(m=>[m.reference,dateLabel(m.at),locName(m.location),s.products.find(p=>p.id===m.product).sku,m.delta,m.reservedDelta,m.reason])];else rows=[['Location','SKU','On hand','Reserved','Available','Quarantine'],...s.balances.map(b=>[locName(b.location),s.products.find(p=>p.id===b.product).sku,b.onHand,b.reserved,b.onHand-b.reserved,b.quarantine])];const csv=rows.map(row=>row.map(v=>'"'+(typeof v==='number'?String(v):String(v).replace(/^[=+@-]/,"'$&")).replaceAll('"','""')+'"').join(',')).join('\r\n');const link=document.createElement('a');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));link.href=url;link.download='optiman-demo-'+kind+'.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('submit',e=>{if(e.target.id==='analytics-filters'){e.preventDefault();analyticsFilters=Object.fromEntries(new FormData(e.target));render();}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-export]');if(b)exportCSV(b.dataset.export);});

function staffOrders(s){return `${staffHeading('Orders & returns','Online orders reserve at a specific eligible location. Completed revenue is recognized once at dispatch. No silent multi-location split.')}<h2>Online order queue</h2>${staffTable(['Reference','Allocation / state','Payment / review','Items / total','Actions'],s.orders.slice().reverse().map(o=>[o.id,`${locName(o.location)}<br>${o.status}`,`${o.payment}<br>${o.review}<br>${o.refundState||''}`,o.items.map(l=>`${esc(l.name)} × ${l.qty} · ${esc(l.lensCategory)}${l.rxType?' / '+esc(rxTypes[l.rxType]||l.rxType):''}`).join('<br>')+'<br>'+money(o.total),`${o.status==='allocation_exception'?`<button class="quiet" data-order-allocate="${o.id}">Resolve single-location allocation</button>`:''}${o.status==='reserved'?`<button class="quiet" data-order-dispatch="${o.id}">Dispatch when verified</button><button class="quiet" data-order-cancel="${o.id}">Cancel / release</button>`:''}${o.status==='allocation_exception'?`<button class="quiet" data-order-cancel="${o.id}">Cancel / refund exception</button>`:''}${o.refundState==='Simulated refund pending'?`<button class="quiet" data-order-refund="${o.id}">Simulate refund completion</button>`:''}<a class="quiet" href="#tracking/${o.id}">Customer tracking preview</a>`]))}<h2>Completed transactions & returns</h2><p class="muted">Seven-day conditional frame returns require policy/inspection review. Prescription/custom exceptions are reviewed separately; this demo does not invent a final policy.</p>${salesHistory(s)}<h2>Return / refund history</h2>${staffTable(['Reference / sale','Branch','Quantity / disposition','Simulated refund','Reason'],s.returns.slice().reverse().map(r=>[`${r.id}<br>${r.sale}`,locName(r.location),`${r.qty} / ${r.disposition}`,money(r.refund),esc(r.reason)]))}`;}
function staffPrescriptions(s){const orders=s.orders.filter(o=>o.review!=='Not required');return `${staffHeading('Prescription review','Only synthetic prescription type is retained in operational records. Actual powers, IPD, filenames and files never enter persistent staff state.')}<p class="notice">No fabrication or dispatch before required verification and customer acceptance of a revised quotation. There is no real production system here.</p>${staffTable(['Order / branch','Synthetic configuration','Review state','Customer acceptance','Action'],orders.map(o=>[`${o.id}<br>${locName(o.location)}`,o.items.filter(l=>l.rxType).map(l=>`${esc(l.name)} · ${esc(rxTypes[l.rxType]||l.rxType)} · ${esc(l.lensCategory)}`).join('<br>'),o.review,o.customerApproved?'Simulated acceptance recorded':o.proposed?'Not accepted':'No revised quote',`<button class="quiet" data-review-order="${o.id}" ${!['reserved','allocation_exception'].includes(o.status)?'disabled':''}>Review / propose quote</button><a class="quiet" href="#tracking/${o.id}">Customer response preview</a>`]))}`;}
function staffLenses(s){return `${staffHeading('Shared lens pricing & eligibility','Synthetic rules only. Both demo roles edit the same business-wide configuration. Existing sale/order price snapshots are preserved.')}<button class="button" id="create-lens-rule">Create synthetic lens rule</button><p>Eligibility bounds are demonstration fixtures, not clinical guidance. Lens cost may remain unknown; gross profit must then be unavailable for lens sales.</p>${staffTable(['Category / option','Rule','Price per pair','Synthetic constraints','Lens cost',''],s.rules.map((r,i)=>[`${esc(r.category)}<br>${esc(r.option)}`,r.type,r.type==='FIXED_PRICE'?money(r.price):'No automatic price',`SPH ≤${r.maxSph??'—'} / CYL ≤${r.maxCyl??'—'} / ADD ≤${r.maxAdd??'—'}`,r.lensCost===null?'Unavailable':money(r.lensCost),`<button class="quiet" data-lens-rule="${i}">Edit shared rule</button>`]))}`;}
function staffSettings(s){return `${staffHeading('Demo settings','Exactly two staff modes. Same modules; only location scope differs. Browser-local settings are not secure authorization.')}<section class="staff-panel"><h2>Role scope</h2><p>Owner: all branches and warehouse. Branch Manager: fixed Khulna branch, with relevant transfers. No cashier, supervisor or separate administrator role.</p><p>One active browser origin shares synthetic state. Web Locks coordinate same-origin commands where supported; without them this is a single active tab demo. No synchronization across devices, browsers or users. Production requires server-side login, authorization and transactional stock.</p></section><form id="settings-form" class="staff-panel"><h2>Demonstration price bands</h2><label>Ascending lower bounds · comma-separated<input name="bands" value="${s.settings.priceBands.join(',')}" required></label><label>Online order delivery charge · BDT<input name="deliveryCharge" type="number" min="0" step=".01" value="${s.settings.deliveryCharge}" required></label><label>Business WhatsApp number · optional<input name="whatsappNumber" inputmode="tel" value="${esc(s.settings.whatsappNumber||'')}" placeholder="Country code and digits, without +" pattern="[1-9][0-9]{6,14}"></label><p>Leave blank until the business supplies its number. Customer inquiries exclude prescription measurements and files.</p><button class="button">Save shared configuration</button></form><section class="staff-panel"><h2>Reset demo fixture</h2><p>This is a test-fixture control, not an operational stock adjustment. It resets all synthetic locations, history and catalog changes in this browser; it clears ephemeral carts and prescriptions too. It does not affect other browsers or any production system.</p><button class="quiet" id="reset-demo">Reset all demo data</button></section>`;}
function returnForm(sale){return `<form id="return-form" data-sale="${sale.id}"><h2>Inspected return / simulated refund</h2><p>${sale.id} · ${locName(sale.location)}</p><label>Sold item<select name="item">${sale.items.map((l,i)=>`<option value="${i}">${esc(l.name)} · sold ${l.qty}</option>`).join('')}</select></label><label>Quantity<input name="qty" type="number" min="1" step="1" value="1" required></label><label>Reason<input name="reason" required placeholder="Synthetic inspection result"></label><label>Inspection / restock disposition<select name="disposition"><option value="quarantine">Quarantine / not sellable</option><option value="sellable">Inspected and eligible for resale</option></select></label><label class="radio-card"><input type="checkbox" required> I reviewed conditional return policy and prescription/custom exceptions for this fictional item.</label><button class="button">Confirm simulated refund once</button><p class="form-error" role="alert"></p></form>`;}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;try{
 if(d.returnSale){const sale=staffData().sales.find(s=>s.id===d.returnSale);if(!sale)throw Error('Sale outside current scope.');modal(returnForm(sale));}
 if(d.orderRefund){await staffCommand('orderRefund',{id:d.orderRefund});render();}
 if(d.orderDispatch){await staffCommand('orderDispatch',{id:d.orderDispatch});render();}
 if(d.orderCancel){await staffCommand('orderCancel',{id:d.orderCancel});render();}
 if(d.orderAllocate){modal(`<form id="order-allocate-form" data-order="${d.orderAllocate}"><h2>Choose one eligible location</h2><label>Fulfillment location${locationSelect('allocate-location')}</label><p>All items must be available at this one location. No split is created.</p><button class="button">Reserve at selected location</button><p class="form-error" role="alert"></p></form>`);}
 if(d.reviewOrder){const o=staffData().orders.find(o=>o.id===d.reviewOrder);modal(`<form id="review-form" data-order="${o.id}"><h2>Review synthetic prescription</h2><label>Decision<select name="review">${['Pending','Needs clarification','Approved','Rejected','Revised quote awaiting customer acceptance'].map(v=>`<option ${v===o.review?'selected':''}>${v}</option>`).join('')}</select></label><label>Lens item for revised quotation<select name="item">${o.items.map((l,i)=>`<option value="${i}">${esc(l.name)} / ${esc(l.lensCategory)}</option>`).join('')}</select></label><label>Proposed lens pair price · only for revised quote<input name="lensPrice" type="number" min="0" step=".01" placeholder="No automatic quote"></label><button class="button">Save review decision</button><p class="form-error" role="alert"></p></form>`);}
 if(d.lensRule!==undefined){const r=D().lensRules()[+d.lensRule];modal(`<form id="lens-rule-form" data-rule="${d.lensRule}"><h2>Shared synthetic lens rule</h2><p>${esc(r.category)} / ${esc(r.option)}</p><label>Customer lens type<select name="lensType">${['White Lens','Anti-Reflective Lens','Blue Cut Lens','Photochromic Lens','Photochromic + Blue Cut Lens'].map(v=>`<option ${r.lensType===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Coating / features<input name="features" value="${esc(r.features||r.option)}"></label><label>Prescription eligibility<select name="prescriptionTypes">${[['zero,unifocal','Zero / Unifocal'],['bifocal','Bifocal'],['progressive','Progressive / Multifocal'],['unifocal,bifocal,progressive','Powered types'],['zero,unifocal,bifocal,progressive','All types'],['unifocal,bifocal','Legacy powered types'],['zero,unifocal,bifocal','Legacy Zero / Unifocal / Bifocal'],['zero','Zero only'],['unifocal','Unifocal only']].map(([v,l])=>`<option value="${v}" ${r.types?.join(',')===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Shape restriction<select name="shape"><option value="">Any configured shape</option><option ${r.shapes?.includes('Moon Shape')?'selected':''}>Moon Shape</option><option ${r.shapes?.includes('Flat Top')?'selected':''}>Flat Top</option></select></label><label>Explicit rule<select name="type">${['FIXED_PRICE','CONSULT_WHATSAPP','UNAVAILABLE'].map(t=>`<option ${r.type===t?'selected':''}>${t}</option>`).join('')}</select></label><label>Pair price · required for FIXED_PRICE<input name="price" type="number" min="0" step=".01" value="${r.price??''}"></label><label>Lens pair cost · blank if unknown<input name="lensCost" type="number" min="0" step=".01" value="${r.lensCost??''}"></label><div class="form-grid"><label>Demo maximum SPH magnitude<input name="maxSph" type="number" min="0" step=".25" value="${r.maxSph??''}"></label><label>Demo maximum CYL magnitude<input name="maxCyl" type="number" min="0" step=".25" value="${r.maxCyl??''}"></label><label>Demo maximum ADD<input name="maxAdd" type="number" min="0" step=".25" value="${r.maxAdd??''}"></label></div><button class="button">Confirm shared price / rule change</button><p class="form-error" role="alert"></p></form>`);}
 if(b.id==='reset-demo')modal('<h2>Reset all browser-local demo data?</h2><p>This deliberately replaces the entire fictional fixture, including all locations, transactions and catalog edits. No production data exists.</p><button class="button" id="confirm-reset-demo">Confirm reset</button><p class="form-error" role="alert"></p>');
 if(b.id==='confirm-reset-demo'){b.disabled=true;await staffCommand('reset',{});cart=[];posTicket=[];receivingLines=[];rxDraft=freshRx();rxPOSContext=null;lastSale=null;lastReceipt=null;document.querySelector('dialog').close();render();}
 }catch(err){const target=document.querySelector('dialog[open] .form-error')||document.querySelector('.staff-message');if(target)target.textContent=err.message;}});
document.addEventListener('submit',async e=>{const f=e.target;if(!['return-form','review-form','lens-rule-form','settings-form','order-allocate-form'].includes(f.id))return;e.preventDefault();const button=f.querySelector('button');try{button.disabled=true;const values=Object.fromEntries(new FormData(f));if(f.id==='return-form')await staffCommand('return',{sale:f.dataset.sale,...values});if(f.id==='review-form')await staffCommand('review',{id:f.dataset.order,...values});if(f.id==='lens-rule-form')await staffCommand('updateRule',{rule:f.dataset.rule,...values});if(f.id==='settings-form')await staffCommand('settings',values);if(f.id==='order-allocate-form')await staffCommand('orderAllocate',{id:f.dataset.order,location:document.querySelector('#staff-allocate-location').value});if(document.querySelector('dialog').open)document.querySelector('dialog').close();render();}catch(err){button.disabled=false;const target=f.querySelector('.form-error')||document.querySelector('.staff-message');if(target)target.textContent=err.message;}});

let checkoutCommand=null;
async function demoOnlineCheckout(){
 const outcome=document.querySelector('#outcome').value,payment=document.querySelector('input[name=payment]:checked').value;
 if(outcome==='failed'){modal('<h2>Simulated payment failure</h2><p>No order, reservation or payment was created. Check status before any real retry.</p>');return;}
 if(!navigator.onLine){modal('<h2>Offline demo</h2><p>No online order can be confirmed while offline.</p>');return;}
 const button=document.querySelector('#checkout-form .button');button.disabled=true;
 try{
  if(!checkoutCommand)checkoutCommand={key:token(),payload:{items:cart.map(l=>({product:l.id,qty:l.qty,rx:l.rx,lensId:l.rx?.lensId??null,rxType:l.rx?.type??null})),payment:outcome==='conflict'?'online':payment,forceException:outcome==='conflict',expectedDelivery:checkoutDeliveryQuote,expectedTotal:cart.reduce((n,l)=>n+(l.price+l.lensPrice)*l.qty,0)}};
  const order=await D().command('online',checkoutCommand.payload,{role:'Public'},checkoutCommand.key);
  checkoutCommand=null;cart=[];
  modal(`<h2>Simulated ${order.status==='reserved'?'order reserved':'allocation exception'}</h2><p>Demo reference: <b>${order.id}</b>. ${order.location?'Allocated at '+locName(order.location)+'. Shared demo availability updated.':'Simulated payment received, but no single location allocated. Staff must resolve or simulate refund; no stock was reserved.'}</p><p>${order.confirmation==='confirmed'?'Advance verified in simulation; order confirmed.':'Order is not confirmed until the required advance is verified.'}</p><p>No real order or money transfer. Medical entries, file metadata and delivery fields were not persisted or transmitted.</p><a class="button" href="#tracking/${order.id}" id="track-demo-order">Track demo order</a>`);
  document.querySelector('#bag-count').textContent='0';
 }catch(err){checkoutCommand=null;modal(`<h2>Demo checkout requires attention</h2><p>${esc(err.message)}</p><p>No confirmed stock mutation was committed.</p>`);button.disabled=false;}
}
function tracking(){const id=location.hash.split('/')[1]||'',o=D().tracking(id);return `${heading('CUSTOMER ORDER TRACKING','Your demo order.','Synthetic browser-local preview only. No real customer/order data.')}<section class="section">${o?`<div class="staff-panel"><h2>${o.id}</h2><p>Status: ${o.status}</p><p>Fulfillment: ${locName(o.location)}</p><p>Payment: ${o.payment} · no money moved</p>${o.paymentPlan?`<p id="order-confirmation">Confirmation: ${o.confirmation}</p>${paymentLines(o.paymentPlan)}<p>Verified advance · simulation: ${money(o.verifiedAdvance||0)}</p>${o.status==='reserved'&&o.confirmation!=='confirmed'?`<button class="button" data-verify-advance="${o.id}" data-amount="${o.paymentPlan.advance}">Simulate advance verification</button><p>No funds are collected. This simulates verification of the required advance.</p>`:''}`:''}<p>Prescription review: ${o.review}</p><p>Illustrative item total: ${money(o.total)}</p>${o.review==='Revised quote awaiting customer acceptance'?`<p>Proposed revised item total: ${money(o.proposedTotal)}. Fabrication/dispatch stays blocked until acceptance.</p><button class="button" data-customer-accept="${o.id}">Simulate customer acceptance</button>`:''}</div>`:'<p>No matching demo order in this browser. Real order tracking requires authenticated backend access.</p>'}</section>`;}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-customer-accept]');if(b){try{await D().command('acceptQuote',{id:b.dataset.customerAccept},{role:'Public'},token());render();}catch(err){note(err.message);}}if(e.target.closest('#track-demo-order'))document.querySelector('dialog').close();});
document.addEventListener('click',e=>{if(e.target.closest('#create-lens-rule'))modal(`<form id="create-lens-form"><h2>New synthetic lens rule</h2><label>Prescription/lens category<input name="category" required></label><label>Lens type / option<input name="option" required></label><label>Customer lens type<select name="lensType">${['White Lens','Anti-Reflective Lens','Blue Cut Lens','Photochromic Lens','Photochromic + Blue Cut Lens'].map(v=>`<option>${v}</option>`).join('')}</select></label><label>Coating / features<input name="features" required></label><label>Prescription eligibility<select name="prescriptionTypes"><option value="zero,unifocal">Zero / Unifocal</option><option value="bifocal">Bifocal</option><option value="progressive">Progressive / Multifocal</option><option value="zero,unifocal,bifocal,progressive">All types</option></select></label><label>Rule<select name="type"><option>FIXED_PRICE</option><option>CONSULT_WHATSAPP</option><option>UNAVAILABLE</option></select></label><label>Pair price · fixed rules only<input name="price" type="number" min="0" step=".01"></label><label>Lens cost · blank unknown<input name="lensCost" type="number" min="0" step=".01"></label><label>Demo max SPH<input name="maxSph" type="number" min="0" step=".25"></label><label>Demo max CYL<input name="maxCyl" type="number" min="0" step=".25"></label><label>Demo max ADD · bifocal / progressive<input name="maxAdd" type="number" min="0" step=".25"></label><button class="button">Create shared rule</button><p class="form-error" role="alert"></p></form>`);});
document.addEventListener('submit',async e=>{if(e.target.id!=='create-lens-form')return;e.preventDefault();try{await staffCommand('createRule',Object.fromEntries(new FormData(e.target)));document.querySelector('dialog').close();render();}catch(err){e.target.querySelector('.form-error').textContent=err.message;}});

document.addEventListener('click',async e=>{const b=e.target.closest('[data-verify-advance]');if(!b)return;b.disabled=true;try{await D().command('verifyAdvance',{id:b.dataset.verifyAdvance,amount:Number(b.dataset.amount)},{role:'Public'},token());render();}catch(err){b.disabled=false;note(err.message);}});
